def update(file,title,desc,h1=None):
 p=ROOT/file;s=p.read_text();s=re.sub(r'<title>.*?</title>',lambda _: '<title>'+html.escape(title)+'</title>',s,count=1,flags=re.S)
 for attr,key,value in [('name','description',desc),('property','og:title',title),('property','og:description',desc),('name','twitter:title',title),('name','twitter:description',desc)]:
  tag=f'<meta {attr}="{key}" content="{html.escape(value,quote=True)}">'
  pattern=rf'<meta {attr}="{key}" content="[^"]*"\s*/?>'
  if re.search(pattern,s):s=re.sub(pattern,lambda _:tag,s,count=1)
  else:s=s.replace('</head>',tag+'\n</head>',1)
 if h1:s=re.sub(r'<h1[^>]*>.*?</h1>',lambda _: '<h1>'+html.escape(h1)+'</h1>',s,count=1,flags=re.S)
 def schema(m):
  obj=json.loads(m[2]);nodes=obj.get('@graph',[obj])
  for node in nodes:
   if node.get('@type') in ['Article','BlogPosting','WebPage']:
    node['description']=desc
    node['headline' if node.get('@type') in ['Article','BlogPosting'] else 'name']=h1 or title
    if node.get('@type') in ['Article','BlogPosting']:node['dateModified']=DATE
  return m[1]+json.dumps(obj,ensure_ascii=False)+m[3]
 s=re.sub(r'(<script[^>]*type="application/ld\+json"[^>]*>)(.*?)(</script>)',schema,s,flags=re.S)
 p.write_text(s)

def block(file,body,early=False):
 p=ROOT/file;s=p.read_text();s=re.sub(r'<!-- first-str:start -->.*?<!-- first-str:end -->','',s,flags=re.S)
 b='<!-- first-str:start --><section class="bg-alt"><div class="wrap wrap-narrow">'+body+'</div></section><!-- first-str:end -->'
 if early:
  m=re.search(r'<section\b[^>]*class="[^"]*hero[^\"]*".*?</section>',s,re.S)
  if m:s=s[:m.end()]+b+s[m.end():]
  else:s=s.replace('</main>',b+'</main>',1)
 else:s=s.replace('</main>',b+'</main>',1)
 p.write_text(s)

